(async()=>{
  const s=ms=>new Promise(r=>setTimeout(r,ms));
  const E=window.__echoes;
  E.cmd('startRun'); await s(250);
  E.cmd('clearRoom'); await s(400);
  const ring1=E.events;
  const off=ring1.filter(e=>e.type==='reward_offer');
  E.cmd('draftTake'); await s(300);
  const ring2=E.events;
  const tk=ring2.filter(e=>e.type==='draft_taken');
  return {
    hasRewardOffer: ring1.some(e=>e.type==='reward_offer'),
    rewardOffer: off.map(e=>JSON.stringify(e)),
    hasDraftTaken: ring2.some(e=>e.type==='draft_taken'),
    draftTaken: tk.map(e=>JSON.stringify(e)),
    typesTail: ring2.slice(-12).map(e=>e.type)
  };
})()
